// Firm reason: 6 (the recorder process, the model's thread and the clock; every decision is Coax).
// Dictation's effects for OpenAgents on Linux (dictation-host.h): Sources/Dictation.swift's
// CoderDictation, on one thread. The Mac's controller queue, its 20 ms timer and its main-queue
// callbacks are dn_pump here, once a frame; its worker queue is the model's worker thread in
// apps/openagents-cli/dictate-native.c, which this file polls and never waits on.
#define _GNU_SOURCE
#include "dictation-host.h"
#include "dictation.h"        // zeron/dictation-linux.coax, generated by build.sh: the zdl_ rules
#include "dictation-face.h"   // the shared controller, as the Mac's host calls it
#include <pthread.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// apps/openagents-cli/dictate-native.c: the clock, the recorder process and the model's worker thread.
int64_t cxdict_now_ms(void);
int64_t cxdict_arg(coax_v_u8 a);
int64_t cxdict_capture_spawn(void);
int64_t cxdict_capture_read(coax_v_f32 out, int64_t timeout_ms);
int64_t cxdict_capture_rate(void);
int64_t cxdict_capture_close(void);
int64_t cxdict_model_open(coax_v_u8 dir, int64_t gpu, coax_v_u8 err);
int64_t cxdict_model_start(coax_v_f32 samples);
int64_t cxdict_model_poll(coax_v_u8 out, int64_t timeout_ms);
int64_t cxdict_model_clear(void);
int64_t cxdict_model_close(void);

enum { SEGMENTS = 8, CALL = 327520, TEXT = 8200, READ = 4096 };
typedef struct { int32_t at, n, lead, trail; } Segment;
struct Dictation {
  void *controller;
  DictationTo to;
  int fixture;
  int64_t fixture_ms;
  char model[4096], recorder[4096];
  char *stand_in;
  int changed;                  // the controller's facts changed: said at the next pump
  uint64_t finished;            // the ticket whose words go out after its facts
  // the recorder: named once, run while the controller admits capture
  int capturing, named, any;
  int64_t opened, last_audio, anchor, delivered;
  // the model: open, or opening on its own thread for the request `opening_epoch`
  int open, opening, close_wanted, opener_ok;
  uint64_t epoch, opening_epoch;
  pthread_t opener;
  atomic_int opener_done;
  // one clip's recognition: job 1 has a segment to give the worker, 2 waits for its words
  uint64_t ticket, call_ticket;
  float *audio, *call;
  Segment segments[SEGMENTS];
  int32_t count;
  int nsegments, segment, job, succeeded;
  int calling;                  // the worker has a call: this job's, or one that was given up
};

static void reconcile(Dictation *d);
static int64_t now_ms(Dictation *d) { return d->fixture ? d->fixture_ms : cxdict_now_ms(); }
static void changed(Dictation *d) { d->changed = 1; }
static void wipe(void *p, size_t n) { if (p && n) { memset(p, 0, n); __asm__ __volatile__("" : : "r"(p) : "memory"); } }

// ---- the recorder

static void stop_capture(Dictation *d) {
  if (d->capturing && !d->fixture) cxdict_capture_close();
  d->capturing = 0;
}
static void capture_fault(Dictation *d, int reason) {
  stop_capture(d); dct_ready(d->controller, 0); dct_fault(d->controller, reason); changed(d);
}
// 0 running; else why not (dictate-native.c: 7 no such program, 3 it could not start).
static int start_recorder(Dictation *d) {
  if (d->named < 0) return 3;
  if (!d->named) {
    d->named = -1;
    for (int i = 0;; i++) {
      uint8_t arg[1024];
      int64_t n = zdl_recorder_arg(i, (coax_v_u8){arg, sizeof arg});
      if (n == 0) break;
      if (n < 0) return 3;
      // a check's stand-in runs in the program's place, with the same arguments
      coax_v_u8 a = i == 0 && d->recorder[0] ? (coax_v_u8){(uint8_t *)d->recorder, (int64_t)strlen(d->recorder)} : (coax_v_u8){arg, n};
      if (cxdict_arg(a) != 0) return 3;
    }
    d->named = 1;
  }
  int st = (int)cxdict_capture_spawn();
  if (st) return st;
  d->opened = cxdict_now_ms(); d->any = 0; d->delivered = 0; d->last_audio = 0;
  return 0;
}

// ---- the model

static void *open_model(void *p) {
  Dictation *d = p;
  uint8_t why[512];
  size_t n = strlen(d->model);
  // The GPU, as on the Mac: CUDA here. The engine refuses rather than fall back to the CPU.
  int64_t got = n ? cxdict_model_open((coax_v_u8){(uint8_t *)d->model, (int64_t)n}, 1, (coax_v_u8){why, sizeof why}) : -1;
  if (got < -1) fprintf(stderr, "OpenAgents: Parakeet did not open: %.*s\n", (int)(-got - 1), (const char *)why);
  else if (got) fprintf(stderr, "OpenAgents: Parakeet did not open%s\n", n ? "" : ": no model folder is named");
  d->opener_ok = got == 0;
  atomic_store(&d->opener_done, 1);
  return NULL;
}
static void close_model(Dictation *d) {
  d->epoch++; d->open = 0; dct_ready(d->controller, 0);
  d->close_wanted = 1;          // once no thread is opening it and no call is running (settle_model)
}
static void settle_model(Dictation *d) {
  if (d->opening && atomic_load(&d->opener_done)) {
    pthread_join(d->opener, NULL); d->opening = 0;
    if (d->opening_epoch == d->epoch) {
      d->open = d->opener_ok;
      if (d->open) reconcile(d); else { dct_fault(d->controller, 2); stop_capture(d); }
      changed(d);
    }
  }
  if (d->close_wanted && !d->opening && !d->calling) { if (!d->stand_in) cxdict_model_close(); d->close_wanted = 0; }
}

// Enabled and active are asked of the Coax; this carries the facts of the model and the recorder
// to it and does what it then admits. Linux asks no permission for the microphone.
static void reconcile(Dictation *d) {
  void *c = d->controller;
  if (!dct_enabled(c)) { stop_capture(d); close_model(d); return; }
  if (!dct_is_active(c)) { stop_capture(d); dct_ready(c, 0); return; }
  if (!d->open) {
    d->close_wanted = 0;
    if (d->opening && d->opening_epoch == d->epoch) return;
    dct_preparing(c, 2); changed(d);
    if (d->opening) { d->opening_epoch = d->epoch; return; }   // closed while it opened, and wanted again
    d->epoch++; d->opening_epoch = d->epoch;
    if (d->stand_in) d->open = 1;
    else {
      atomic_store(&d->opener_done, 0); d->opener_ok = 0;
      if (pthread_create(&d->opener, NULL, open_model, d)) { dct_fault(c, 2); stop_capture(d); return; }
      d->opening = 1;
      return;
    }
  }
  dct_ready(c, 1);
  if (!d->capturing && dct_capture_allowed(c)) {
    dct_preparing(c, 3);
    if (d->fixture || start_recorder(d) == 0) { d->capturing = 1; dct_ready(c, 1); }
    else capture_fault(d, 3);
  }
}

// ---- one clip's recognition

static void drop_job(Dictation *d) {
  if (d->audio) wipe(d->audio, (size_t)d->count * sizeof *d->audio);
  free(d->audio); d->audio = NULL; d->count = 0; d->job = 0;
}
static int current(Dictation *d) { return dct_ticket(d->controller) == d->ticket && dct_phase(d->controller) == 5; }
static void finish(Dictation *d) {
  uint64_t ticket = d->ticket;
  int ok = d->succeeded;
  drop_job(d);
  if (dct_ticket(d->controller) != ticket) return;
  int accepted = dct_result(d->controller, ticket, ok);
  changed(d);
  if (accepted) d->finished = ticket;
}
static void heard(Dictation *d, const uint8_t *text, int n);
// The next segment to the worker: the Coax's cut, with its silence before and after. The silence
// is the model's input only; it never moves the place in the clip.
static void call_next(Dictation *d) {
  if (d->job != 1 || d->calling) return;   // the worker still has a call that was given up
  if (!current(d)) { drop_job(d); return; }
  Segment s = d->segments[d->segment];
  if (d->stand_in) { d->job = 2; heard(d, (const uint8_t *)d->stand_in, (int)strlen(d->stand_in)); return; }
  int64_t n = (int64_t)s.lead + s.n + s.trail;
  int bad = n < 320 || n > CALL;
  if (!bad) {
    memset(d->call, 0, (size_t)n * sizeof *d->call);
    memcpy(d->call + s.lead, d->audio + s.at, (size_t)s.n * sizeof *d->call);
    bad = cxdict_model_start((coax_v_f32){d->call, n}) != 0;   // the worker copies them
    wipe(d->call, (size_t)n * sizeof *d->call);
  }
  if (bad) { d->succeeded = 0; finish(d); return; }
  d->calling = 1; d->call_ticket = d->ticket; d->job = 2;
}
static void heard(Dictation *d, const uint8_t *text, int n) {
  if (!current(d) || !dct_append_text(d->controller, d->ticket, text, n)) { d->succeeded = 0; finish(d); return; }
  d->segment++;
  if (d->segment == d->nsegments) { finish(d); return; }
  d->job = 1; call_next(d);
}
static void poll_call(Dictation *d) {
  if (d->calling) {
    uint8_t text[TEXT];
    int64_t got = cxdict_model_poll((coax_v_u8){text, sizeof text}, 0);
    if (got == -1) return;      // still running
    d->calling = 0;
    cxdict_model_clear();       // the engine's work for that audio; only the copied words are kept
    if (d->job == 2 && d->call_ticket == d->ticket) {
      if (got >= 0) heard(d, text, (int)got); else { d->succeeded = 0; finish(d); }
    }
    wipe(text, sizeof text);
  }
  call_next(d);
}
// A frozen clip: its samples and the Coax's segments are copied out, and its first call starts.
static void consider(Dictation *d) {
  void *c = d->controller;
  if (dct_phase(c) != 4) return;
  uint64_t ticket = dct_ticket(c);
  int32_t count = dct_samples(c), at = 0;
  int n = 0;
  drop_job(d);
  float *audio = count > 0 ? malloc((size_t)count * sizeof *audio) : NULL;
  int ok = audio && dct_copy_audio(c, 0, audio, count) == count;
  for (int32_t k; ok && (k = dct_segment(c, at)) > 0; at += k) {
    if (n == SEGMENTS) { ok = 0; break; }
    d->segments[n++] = (Segment){at, k, dct_segment_leading_silence(c, at), dct_segment_trailing_silence(c, at)};
  }
  if (!ok || at != count || !dct_decode_begin(c, ticket)) {
    if (audio) wipe(audio, (size_t)count * sizeof *audio);
    free(audio); dct_fault(c, 4); changed(d);
    return;
  }
  changed(d);
  d->ticket = ticket; d->audio = audio; d->count = count; d->nsegments = n; d->segment = 0; d->succeeded = 1; d->job = 1;
  call_next(d);
}

// ---- audio and the clock

static void audio(Dictation *d, const float *mono, int n, int rate, int64_t first) {
  void *c = d->controller;
  int phase = dct_phase(c), outcome = dct_outcome(c), fault = dct_fault_reason(c);
  dct_audio(c, mono, n, rate, first);
  if (dct_outcome(c) == 4 && (outcome != 4 || fault != dct_fault_reason(c))) capture_fault(d, dct_fault_reason(c));
  consider(d);
  if (phase != dct_phase(c) || outcome != dct_outcome(c)) changed(d);
}
static void poll(Dictation *d) {
  void *c = d->controller;
  int phase = dct_phase(c), outcome = dct_outcome(c);
  dct_tick(c, now_ms(d));
  if (outcome != 4 && dct_outcome(c) == 4) capture_fault(d, dct_fault_reason(c));
  consider(d);
  if (phase != dct_phase(c) || outcome != dct_outcome(c)) changed(d);
}
// Everything the recorder has written. Its pipe has no clock: the Coax times each buffer from the
// samples delivered, and says when a recorder that writes nothing has failed.
static void read_recorder(Dictation *d) {
  if (!d->capturing || d->fixture) return;
  static float buf[READ];
  int64_t now = cxdict_now_ms();
  for (int i = 0; i < 64; i++) {
    int64_t n = cxdict_capture_read((coax_v_f32){buf, READ}, 0);
    if (n < 0) { capture_fault(d, 3); break; }
    if (n == 0) break;
    int64_t rate = cxdict_capture_rate();
    if (!d->any) { d->anchor = zdl_anchor(now, n, rate); d->any = 1; }
    int64_t first = zdl_stamp(d->anchor, d->delivered, rate);
    d->delivered += n; d->last_audio = now;
    if (dct_capture_allowed(d->controller)) audio(d, buf, (int)n, (int)rate, first);
    if (!d->capturing) break;   // a fault ended it
  }
  wipe(buf, sizeof buf);
  if (!d->capturing) return;
  if (zdl_stalled(now, d->opened, d->last_audio, d->any)) capture_fault(d, 3);
  else if (d->any && zdl_adrift(dct_phase(d->controller), now, d->anchor, d->delivered, cxdict_capture_rate())) {
    // its count of samples no longer tells the time: started again, as when the window is given the keyboard
    stop_capture(d); dct_ready(d->controller, 0); reconcile(d); changed(d);
  }
}

// ---- the host's calls

Dictation *dn_new(int fixture, const char *model, const char *stand_in, const char *recorder, DictationTo to) {
  Dictation *d = calloc(1, sizeof *d);
  if (!d) return NULL;
  d->controller = dct_new(); d->call = calloc(CALL, sizeof *d->call);
  if (!d->controller || !d->call) { dct_free(d->controller); free(d->call); free(d); return NULL; }
  d->to = to; d->fixture = fixture != 0;
  snprintf(d->model, sizeof d->model, "%s", model ? model : "");
  snprintf(d->recorder, sizeof d->recorder, "%s", recorder ? recorder : "");
  if (stand_in) d->stand_in = strdup(stand_in);
  atomic_init(&d->opener_done, 0);
  return d;
}
void dn_enable(Dictation *d, int on) { dct_enable(d->controller, on != 0, now_ms(d)); reconcile(d); changed(d); }
void dn_activate(Dictation *d) { dct_active(d->controller, 1); reconcile(d); changed(d); }
void dn_deactivate(Dictation *d) { dct_active(d->controller, 0); stop_capture(d); dct_ready(d->controller, 0); changed(d); }
uint64_t dn_begin(Dictation *d) { uint64_t ticket = dct_begin(d->controller, now_ms(d)); changed(d); return ticket; }
void dn_end(Dictation *d) { dct_release(d->controller, now_ms(d)); poll(d); }
void dn_cancel(Dictation *d) { dct_cancel(d->controller); changed(d); }
int dn_ready(Dictation *d) { return dct_capture_allowed(d->controller) != 0; }
void dn_pump(Dictation *d) {
  void *c = d->controller;
  settle_model(d);
  read_recorder(d);
  poll(d);
  poll_call(d);
  if (d->changed) {
    d->changed = 0;
    if (d->to.state) d->to.state(d->to.user, dct_phase(c), dct_outcome(c), dct_fault_reason(c), dct_preparing_reason(c));
  }
  if (d->finished) {
    uint64_t ticket = d->finished;
    d->finished = 0;
    if (dct_ticket(c) == ticket && dct_outcome(c) == 5 && dct_capture_allowed(c)) {
      uint8_t text[TEXT];
      int32_t n = dct_text_count(c);
      if (n >= 0 && n <= (int32_t)sizeof text && dct_copy_text(c, text, n) == n && d->to.words) d->to.words(d->to.user, ticket, text, n);
      wipe(text, sizeof text);
    }
  }
}
void dn_fixture_time(Dictation *d, int64_t ms) { if (d->fixture) { d->fixture_ms = ms; poll(d); } }
void dn_fixture_audio(Dictation *d, const float *mono, int n, int rate, int64_t first_ms) {
  if (d->fixture && dct_capture_allowed(d->controller)) audio(d, mono, n, rate, first_ms);
}
void dn_inspect(Dictation *d, int *phase, int *outcome, int *samples) {
  *phase = dct_phase(d->controller); *outcome = dct_outcome(d->controller); *samples = dct_samples(d->controller);
}
void dn_close(Dictation *d) {
  if (!d) return;
  dct_enable(d->controller, 0, now_ms(d)); stop_capture(d); close_model(d); drop_job(d);
  if (d->opening) { pthread_join(d->opener, NULL); d->opening = 0; }   // it holds this memory until it is done
  if (!d->stand_in) cxdict_model_close();   // a call still running keeps the engine, and ends with the process
  wipe(d->call, (size_t)CALL * sizeof *d->call);
  free(d->call); free(d->stand_in); dct_free(d->controller); free(d);
}
// The pinned model's folder: OPENAGENTS_PARAKEET_MODEL, else the shared model home.
int dn_model_dir(char *out, int cap) {
  const char *named = getenv("OPENAGENTS_PARAKEET_MODEL"), *cache = getenv("OPENAGENTS_MODEL_CACHE"), *home = getenv("HOME");
  if (!named) named = "";
  if (!cache) cache = "";
  if (!home) home = "";
  if (cap < 1) return 0;
  int64_t n = zdl_model_dir((coax_string){named, (int64_t)strlen(named)}, (coax_string){cache, (int64_t)strlen(cache)},
                            (coax_string){home, (int64_t)strlen(home)}, (coax_v_u8){(uint8_t *)out, cap - 1});
  out[n > 0 ? n : 0] = 0;
  return (int)n;
}
